/** * FrameX Authentication System * Quản lý đăng nhập,session,và bảo mật cho Admin Panel * Version:1.0.0 */ class AuthSystem{constructor(){this.SESSION_KEY = 'framex_admin_session';this.REMEMBER_KEY = 'framex_admin_remember';this.SESSION_TIMEOUT = 30 * 60 * 1000;this.REMEMBER_DURATION = 30 * 24 * 60 * 60 * 1000;this.HASHED_CREDENTIALS ={username:'admin',passwordHash:'1184da3414885edd1d4319b9ddbe78e46abbc33d5b444162f05e958fc3021bf1'};this.lastActivity = Date.now();this.activityCheckInterval = null;this.init();}/** * Initialize authentication system */ init(){this.checkRememberedLogin();if(this.isAuthenticated()){this.startActivityMonitoring();}['mousedown','keydown','scroll','touchstart'].forEach(event =>{document.addEventListener(event,()=>{this.updateActivity();},{passive:true});});}/** * Login with username and password */ async login(username,password,rememberMe = false){try{if(this.validateCredentials(username,password)){const sessionData ={username:username,loginTime:Date.now(),lastActivity:Date.now(),isAdmin:true};sessionStorage.setItem(this.SESSION_KEY,JSON.stringify(sessionData));if(rememberMe){const rememberData ={username:username,token:this.generateToken(),expiry:Date.now()+ this.REMEMBER_DURATION};localStorage.setItem(this.REMEMBER_KEY,JSON.stringify(rememberData));}this.startActivityMonitoring();this.logActivity('login',{username});return{success:true,message:'Đăng nhập thành công'};}else{this.logActivity('login_failed',{username});return{success:false,message:'Tên đăng nhập hoặc mật khẩu không đúng'};}}catch(error){console.error('Login error:',error);return{success:false,message:'Lỗi đăng nhập. Vui lòng thử lại.'};}}/** * Validate user credentials with SHA-256 hashing */ async validateCredentials(username,password){const passwordHash = await this.hashPassword(password);return username === this.HASHED_CREDENTIALS.username && passwordHash === this.HASHED_CREDENTIALS.passwordHash;}/** * Hash password using SHA-256 */ async hashPassword(password){const encoder = new TextEncoder();const data = encoder.encode(password);const hashBuffer = await crypto.subtle.digest('SHA-256',data);const hashArray = Array.from(new Uint8Array(hashBuffer));const hashHex = hashArray.map(b => b.toString(16).padStart(2,'0')).join('');return hashHex;}/** * Check if user is authenticated */ isAuthenticated(){const sessionData = this.getSessionData();if(!sessionData){return false;}const now = Date.now();const timeSinceActivity = now - sessionData.lastActivity;if(timeSinceActivity > this.SESSION_TIMEOUT){this.logout(false);return false;}return true;}/** * Get current session data */ getSessionData(){try{const data = sessionStorage.getItem(this.SESSION_KEY);return data ? JSON.parse(data):null;}catch(error){console.error('Error getting session data:',error);return null;}}/** * Update last activity timestamp */ updateActivity(){if(!this.isAuthenticated())return;const sessionData = this.getSessionData();if(sessionData){sessionData.lastActivity = Date.now();sessionStorage.setItem(this.SESSION_KEY,JSON.stringify(sessionData));this.lastActivity = Date.now();}}/** * Start activity monitoring */ startActivityMonitoring(){if(this.activityCheckInterval){clearInterval(this.activityCheckInterval);}this.activityCheckInterval = setInterval(()=>{if(!this.isAuthenticated()){this.handleSessionTimeout();}},60000);}/** * Handle session timeout */ handleSessionTimeout(){clearInterval(this.activityCheckInterval);alert('Phiên làm việc đã hết hạn do không có hoạt động. Vui lòng đăng nhập lại.');window.location.href = 'admin-login.html';}/** * Check for remembered login */ checkRememberedLogin(){try{const rememberData = localStorage.getItem(this.REMEMBER_KEY);if(!rememberData)return;const data = JSON.parse(rememberData);const now = Date.now();if(data.expiry > now){const sessionData ={username:data.username,loginTime:now,lastActivity:now,isAdmin:true,remembered:true};sessionStorage.setItem(this.SESSION_KEY,JSON.stringify(sessionData));}else{localStorage.removeItem(this.REMEMBER_KEY);}}catch(error){console.error('Error checking remembered login:',error);localStorage.removeItem(this.REMEMBER_KEY);}}/** * Check if user has remember me enabled */ isRemembered(){return localStorage.getItem(this.REMEMBER_KEY)!== null;}/** * Logout user */ logout(redirect = true){sessionStorage.removeItem(this.SESSION_KEY);localStorage.removeItem(this.REMEMBER_KEY);if(this.activityCheckInterval){clearInterval(this.activityCheckInterval);}this.logActivity('logout');if(redirect){window.location.href = 'admin-login.html';}}/** * Force logout and clear all data */ forceLogout(){sessionStorage.removeItem(this.SESSION_KEY);localStorage.removeItem(this.REMEMBER_KEY);if(this.activityCheckInterval){clearInterval(this.activityCheckInterval);}window.location.href = 'admin-login.html';}/** * Get current user info */ getCurrentUser(){const sessionData = this.getSessionData();return sessionData ?{username:sessionData.username,loginTime:sessionData.loginTime,isAdmin:sessionData.isAdmin}:null;}/** * Generate random token */ generateToken(){return Math.random().toString(36).substring(2)+ Date.now().toString(36)+ Math.random().toString(36).substring(2);}/** * Log user activity for security audit */ logActivity(action,data ={}){const log ={timestamp:new Date().toISOString(),action:action,username:this.getCurrentUser()?.username || 'unknown',...data};const logs = this.getActivityLogs();logs.unshift(log);if(logs.length > 100){logs.splice(100);}localStorage.setItem('framex_activity_logs',JSON.stringify(logs));}/** * Get activity logs */ getActivityLogs(){try{const logs = localStorage.getItem('framex_activity_logs');return logs ? JSON.parse(logs):[];}catch(error){return [];}}/** * Check HTTPS connection */ isSecureConnection(){return window.location.protocol === 'https:' || window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';}/** * Get security recommendations */ getSecurityRecommendations(){const recommendations = [];if(!this.isSecureConnection()){recommendations.push({level:'critical',message:'Bật HTTPS để bảo vệ mật khẩu và dữ liệu',icon:'fa-exclamation-triangle'});}if(this.DEFAULT_CREDENTIALS.password === 'framex2024'){recommendations.push({level:'high',message:'Đổi mật khẩu mặc định ngay lập tức',icon:'fa-key'});}recommendations.push({level:'medium',message:'Backup database định kỳ(mỗi tuần)',icon:'fa-database'});recommendations.push({level:'low',message:'Kiểm tra activity logs thường xuyên',icon:'fa-history'});return recommendations;}/** * Change password(placeholder for future implementation)*/ changePassword(currentPassword,newPassword){return{success:false,message:'Tính năng đổi mật khẩu cần kết nối với backend. Vui lòng liên hệ quản trị viên.'};}}const Auth = new AuthSystem();if(typeof module !== 'undefined' && module.exports){module.exports = Auth;}